questionvariables.text:
/* Randomize slope (m) to be non-zero integers */
m : rand([1, 2, -1, -2]);

/* Randomize x-intercept to be a non-zero integer */
x_int_temp : rand_with_step(-4, 4, 1);
x_int : if is(x_int_temp = 0) then 2 else x_int_temp;

/* Calculate y-intercept (c) so that 0 = m*x_int + c */
c : -m * x_int;

/* Target Answers */
ta1 : c;
ta2 : x_int;

/* These target variables must be mathematically correct to pass the PRT nodes when the 'Fill in correct responses' button is used */
ta3 : [0, c];         /* Correct y-intercept */
ta4 : [x_int, 0];     /* Correct x-intercept */
ta5 : [0, c + 4];     /* A guaranteed point in the y > mx + c region */

/* Text variables for the worked solution */
origin_statement : if is(0 > c) then "is <b>true</b>, so the origin \\((0,0)\\) belongs in the solution region" else "is <b>false</b>, so the origin \\((0,0)\\) is NOT in the solution region";

feedbackvariables.text:
/* Extract coordinates of the two blue points */
x1 : ans3[1];
y1 : ans3[2];
x2 : ans4[1];
y2 : ans4[2];

/* Extract coordinate of the green region marker */
rx : ans5[1];
ry : ans5[2];
